export const COLORS=['#315ae8','#e0556c','#258d69','#c09614','#8355bc','#d77428','#bc4e92','#218d9c','#485762','#8b704d','#606bbc','#669331'];
export const SPORTS={
 basket:{name:'Basket-ball',icon:'basketball',formats:[['3x3','3 contre 3',3,'half',11],['5x5','5 contre 5',5,'basket',21],['custom','Personnalisé',3,'basket',11]]},
 football:{name:'Football',icon:'football',formats:[['5x5','5 contre 5',5,'football',3],['8x8','8 contre 8',8,'football',3],['11x11','11 contre 11',11,'football',3],['futsal','Futsal',5,'football',3],['custom','Personnalisé',5,'football',3]]},
 futsal:{name:'Futsal',icon:'football',formats:[['5x5','5 contre 5',5,'football',3],['custom','Personnalisé',5,'football',3]]},
 handball:{name:'Handball',icon:'handball',formats:[['7x7','7 contre 7',7,'handball',5],['4x4','4 contre 4',4,'handball',5],['custom','Personnalisé',4,'handball',5]]},
 volley:{name:'Volley-ball',icon:'volley',formats:[['6x6','6 contre 6',6,'volley',15],['4x4','4 contre 4',4,'volley',15],['2x2','2 contre 2',2,'volley',15],['custom','Personnalisé',4,'volley',15]]},
 badminton:{name:'Badminton',icon:'racket',formats:[['single','Simple',1,'badminton',11],['double','Double',2,'badminton',11]]},
 table:{name:'Tennis de table',icon:'table',formats:[['single','Simple',1,'table',11],['double','Double',2,'table',11]]},
 tennis:{name:'Tennis',icon:'racket',formats:[['single','Simple',1,'tennis',15],['double','Double',2,'tennis',15]]},
 rugby:{name:'Rugby',icon:'rugby',formats:[['5x5','Toucher 5 contre 5',5,'rugby',3],['7x7','7 contre 7',7,'rugby',3],['15x15','15 contre 15',15,'rugby',3],['custom','Personnalisé',5,'rugby',3]]},
 ultimate:{name:'Ultimate',icon:'disc',formats:[['5x5','5 contre 5',5,'ultimate',5],['custom','Personnalisé',5,'ultimate',5]]},
 hockey:{name:'Hockey',icon:'hockey',formats:[['5x5','5 contre 5',5,'hockey',3],['custom','Personnalisé',5,'hockey',3]]},
 custom:{name:'Activité personnalisée',icon:'trophy',formats:[['custom','Personnalisé',1,'custom',10]]}
};
export const FORMULAS={rr:'Championnat · tous se rencontrent',pools:'Poules',poolfinal:'Poules + phases finales',classification:'Matchs de classement',knockout:'Élimination directe',double:'Double élimination',swiss:'Ronde suisse',ladder:'Montante-descendante',king:'King / Queen of the Court',americano:'Americano · partenaires tournants',levels:'Groupes de niveaux',custom:'Rencontres personnalisées'};
export const uid=()=>globalThis.crypto?.randomUUID?.()??'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
export const ids=x=>Array.isArray(x)?x:[x];
export const entrants=m=>[...ids(m.a),...ids(m.b)];
export const done=m=>['done','cancelled'].includes(m.status);
export const allMatches=t=>t.rotations.flatMap(r=>r.matches);
export const current=t=>t.rotations[t.roundIndex];
export const team=(t,id)=>t.teams.find(x=>x.id===id);
export const label=(t,side)=>ids(side).map(id=>team(t,id)?.name??'?').join(' + ');
export const formatTime=ms=>{const s=Math.max(0,Math.ceil(ms/1000));return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`};
export const clockLeft=(c,now=Date.now())=>c?.status==='running'?Math.max(0,c.deadline-now):(c?.remaining??0);
export const hasTime=t=>['time','hybrid'].includes(t.config.endMode);
export const hasTarget=t=>['score','hybrid'].includes(t.config.endMode);
export const eliminate=t=>['knockout','double','classification'].includes(t.config.formula)||t.engine.phase==='finals';
export const decisive=t=>eliminate(t)||['ladder','king'].includes(t.config.formula);
function checkpoint(t){const {history,...state}=t.engine;t.engine.history??={};t.engine.history[t.engine.stage]=structuredClone(state)}
export function makeTeams(n){return Array.from({length:n},(_,i)=>({id:uid(),name:`Équipe ${i+1}`,color:COLORS[i%COLORS.length],members:[],level:0,active:true}))}
function clock(ms){return {status:'ready',remaining:ms,deadline:null,alerts:[]}}
function match(p,court,stage){return {id:p.id??uid(),a:ids(p.a),b:ids(p.b),courtId:court.id,scoreA:p.scoreA??0,scoreB:p.scoreB??0,status:p.status??'scheduled',group:p.group??'',phase:p.phase??'',stage,track:p.track??null,clock:p.clock??null,tieBreak:p.tieBreak??null,reason:p.reason??null}}
export function roundRobin(roster){const v=roster.slice();if(v.length%2)v.push(null);const out=[];for(let k=0;k<v.length-1;k++){const pairs=[];for(let i=0;i<v.length/2;i++){const a=v[i],b=v[v.length-1-i];if(a&&b)pairs.push({a:k%2?b:a,b:k%2?a:b})}out.push(pairs);v.splice(1,0,v.pop())}return out}
function pack(pending,cap,last,index){cap=Math.min(cap,pending.length);let best=[];let visits=0;const ordered=pending.slice().sort((x,y)=>(Math.max(last.get(ids(x.a)[0])??-10,last.get(ids(x.b)[0])??-10)-Math.max(last.get(ids(y.a)[0])??-10,last.get(ids(y.b)[0])??-10)));
 const dfs=(at,picked,used)=>{if(++visits>4000)return false;if(picked.length>best.length)best=picked.slice();if(picked.length===cap)return true;if(ordered.length-at<cap-picked.length)return false;for(let i=at;i<ordered.length;i++){const p=ordered[i],who=[...ids(p.a),...ids(p.b)];if(who.some(id=>used.has(id)))continue;who.forEach(id=>used.add(id));picked.push(p);if(dfs(i+1,picked,used))return true;picked.pop();who.forEach(id=>used.delete(id))}return false};dfs(0,[],new Set());return best;
}
export function schedule(t,pairs,logical=null,stage=0){const courts=t.courts.filter(c=>c.available);if(!courts.length)throw Error('Il faut au moins un terrain disponible.');let batches=[];
 if(logical&&logical.every(r=>r.length<=courts.length))batches=logical.filter(r=>r.length);else{const pending=pairs.slice(),last=new Map();while(pending.length){const choice=pack(pending,courts.length,last,batches.length);if(!choice.length)throw Error('Rencontre invalide.');batches.push(choice);for(const p of choice){pending.splice(pending.indexOf(p),1);[...ids(p.a),...ids(p.b)].forEach(id=>last.set(id,batches.length))}}}
 const use=new Map();for(const b of batches){const available=courts.slice();const matches=b.map(p=>{available.sort((a,b)=>[...ids(p.a),...ids(p.b)].reduce((n,id)=>n+(use.get(id+'|'+a.id)??0)-(use.get(id+'|'+b.id)??0),0));const c=available.shift();[...ids(p.a),...ids(p.b)].forEach(id=>use.set(id+'|'+c.id,(use.get(id+'|'+c.id)??0)+1));return match(p,c,stage)});t.rotations.push({id:uid(),number:t.rotations.length+1,stage,matches,clock:clock(t.config.duration*1000)})}
}
export function newTournament(config={},teams=makeTeams(8)){
 const cfg={sport:'basket',format:'3x3',formula:'rr',courtCount:4,endMode:'time',duration:300,target:11,sync:'common',stopPolicy:'individual',tie:'draw',overtime:60,breakSeconds:30,poolCount:2,qualifiers:2,roundCount:7,availableMinutes:0,winPoints:3,drawPoints:1,lossPoints:0,...config};
 if(!SPORTS[cfg.sport]||!FORMULAS[cfg.formula]||!['time','score','hybrid','free'].includes(cfg.endMode))throw Error('Sport, formule ou règle de fin invalide.');
 if(!Number.isFinite(cfg.duration)||cfg.duration<15||cfg.duration>7200||!Number.isInteger(cfg.target)||cfg.target<1||cfg.target>999)throw Error('La durée et le score cible doivent être positifs.');
 if(!Number.isInteger(cfg.roundCount)||cfg.roundCount<1||cfg.roundCount>50||!Number.isInteger(cfg.poolCount)||cfg.poolCount<1||cfg.poolCount>8||!Number.isInteger(cfg.qualifiers)||cfg.qualifiers<1||cfg.qualifiers>4)throw Error('Nombre de rondes, poules ou qualifiés invalide.');
 if(!Number.isFinite(cfg.overtime)||cfg.overtime<10||cfg.overtime>3600||!Number.isFinite(cfg.breakSeconds)||cfg.breakSeconds<0||cfg.breakSeconds>600)throw Error('Durée de récupération ou de prolongation invalide.');
 if([cfg.winPoints,cfg.drawPoints,cfg.lossPoints,cfg.availableMinutes].some(x=>!Number.isFinite(x)||x<0))throw Error('Les points et la durée disponible doivent être positifs ou nuls.');
 if(cfg.scoreMode!==undefined&&!['normal','bonus'].includes(cfg.scoreMode))throw Error('Comptage des points invalide.');
 if(cfg.scoreMode==='bonus'&&(!Number.isInteger(cfg.bonusPoints)||cfg.bonusPoints<2||cfg.bonusPoints>20))throw Error('Le bonus doit valoir entre 2 et 20 points.');
 if(!Number.isInteger(cfg.courtCount)||cfg.courtCount<1||cfg.courtCount>24)throw Error('Choisissez entre 1 et 24 terrains.');if(teams.length<2||teams.length>64)throw Error('Choisissez entre 2 et 64 équipes ou joueurs.');if(cfg.formula==='americano'&&teams.length<4)throw Error('L’Americano nécessite au moins quatre joueurs.');
 const t={id:uid(),config:cfg,teams:structuredClone(teams),courts:Array.from({length:cfg.courtCount},(_,i)=>({id:uid(),name:(cfg.sport==='table'?'Table ':cfg.sport==='basket'&&cfg.format==='3x3'?'Demi-terrain ':'Terrain ')+(i+1),available:true})),rotations:[],roundIndex:0,completed:false,engine:{stage:0,phase:'main',byes:{},placements:{},wait:[],groups:[]},audit:[]};
 const roster=t.teams.map(x=>x.id);
 if(cfg.formula==='rr'){const rounds=roundRobin(roster);schedule(t,rounds.flat(),rounds)}
 else if(['pools','poolfinal','levels'].includes(cfg.formula)){const count=Math.max(1,Math.min(cfg.poolCount,Math.floor(roster.length/2)));const ordered=cfg.formula==='levels'?t.teams.slice().sort((a,b)=>b.level-a.level):t.teams.slice();const groups=Array.from({length:count},(_,i)=>({name:'Poule '+String.fromCharCode(65+i),ids:[]}));ordered.forEach((x,i)=>groups[cfg.formula==='levels'?Math.min(count-1,Math.floor(i*count/ordered.length)):(Math.floor(i/count)%2?count-1-i%count:i%count)].ids.push(x.id));t.engine.groups=groups;const pairs=groups.flatMap(g=>roundRobin(g.ids).flat().map(p=>({...p,group:g.name,phase:'Poules'})));schedule(t,pairs)}
 else if(['knockout','classification'].includes(cfg.formula)){t.engine.tracks=[{ids:roster,start:1}];generateBracket(t)}
 else if(cfg.formula==='custom'){if(!cfg.customPairs?.length)throw Error('Ajoutez les rencontres personnalisées.');const pairs=cfg.customPairs.map(p=>({a:roster[p[0]],b:roster[p[1]]}));if(pairs.some(p=>!p.a||!p.b||p.a===p.b))throw Error('Une rencontre personnalisée est invalide.');schedule(t,pairs)}
 else generateDynamic(t);
 checkpoint(t);return t;
}
export function standings(t,group=null){const entries=t.teams.filter(x=>!group||group.includes(x.id)).map(x=>({id:x.id,name:x.name,color:x.color,played:0,wins:0,draws:0,losses:0,for:0,against:0,points:0,active:x.active,rank:0}));const map=new Map(entries.map(x=>[x.id,x]));for(const m of allMatches(t)){if(m.status!=='done')continue;for(const [side,other,sc,ag]of[[m.a,m.b,m.scoreA,m.scoreB],[m.b,m.a,m.scoreB,m.scoreA]])for(const id of ids(side)){const e=map.get(id);if(!e)continue;e.played++;e.for+=sc;e.against+=ag;if(sc>ag){e.wins++;e.points+=t.config.winPoints}else if(sc===ag){e.draws++;e.points+=t.config.drawPoints}else{e.losses++;e.points+=t.config.lossPoints}}}
 if(t.config.formula==='swiss')for(const e of entries)e.points+=(t.engine.byes[e.id]??0)*t.config.winPoints;
 entries.sort((a,b)=>{if(t.completed&&(t.engine.placements[a.id]||t.engine.placements[b.id]))return(t.engine.placements[a.id]??999)-(t.engine.placements[b.id]??999);return(t.config.formula==='americano'?b.for-a.for:b.points-a.points)||(b.for-b.against)-(a.for-a.against)||b.for-a.for||a.name.localeCompare(b.name,'fr')});entries.forEach((e,i)=>e.rank=i+1);return entries;
}
function winner(m){if(m.reason==='both-absent'||m.status==='cancelled')return null;return m.scoreA>m.scoreB?m.a:m.scoreB>m.scoreA?m.b:null}
function loser(m){const w=winner(m);return w===m.a?m.b:w===m.b?m.a:null}
function generateBracket(t){const pairs=[];t.engine.bracket=[];for(const [track,g]of t.engine.tracks.entries()){if(g.ids.length===1){t.engine.placements[g.ids[0]]=g.start;continue}const entry={track,start:g.start,byes:[],ids:g.ids};let v=g.ids.slice();if(v.length%2)entry.byes.push(v.shift());while(v.length){const a=v.shift(),b=v.pop();pairs.push({a,b,track,phase:g.start===1&&g.ids.length===2?'Finale':`Places ${g.start} à ${g.start+g.ids.length-1}`})}t.engine.bracket.push(entry)}if(!pairs.length){t.completed=true;return false}schedule(t,pairs,null,++t.engine.stage);checkpoint(t);return true}
function nextBracket(t){const previous=t.rotations.flatMap(r=>r.stage===t.engine.stage?r.matches:[]);const tracks=[];for(const g of t.engine.bracket){const ms=previous.filter(m=>m.track===g.track);if(ms.some(m=>!done(m)||m.status!=='cancelled'&&!winner(m)))return false;const winners=[...g.byes.filter(id=>team(t,id)?.active),...ms.flatMap(m=>winner(m)??[])],losers=ms.flatMap(m=>loser(m)??[]);if(winners.length)tracks.push({ids:winners,start:g.start});if(t.config.formula==='classification'&&losers.length)tracks.push({ids:losers,start:g.start+winners.length});else for(const id of losers)t.engine.placements[id]=g.start+winners.length}t.engine.tracks=tracks;return generateBracket(t)}
function pairSwiss(t,roster){const played=new Set(allMatches(t).filter(done).map(m=>[...m.a,...m.b].sort().join('|')));let best=null,bestCost=Infinity,visits=0;function dfs(v,p,cost){if(++visits>10000||cost>=bestCost)return;if(!v.length){best=p.slice();bestCost=cost;return}const a=v[0];for(let j=1;j<v.length;j++){const b=v[j],key=[a,b].sort().join('|');const add=(played.has(key)?1000:0)+j-1;dfs(v.slice(1,j).concat(v.slice(j+1)),p.concat({a,b,phase:'Ronde suisse'}),cost+add)}}dfs(roster,[],0);return best??roster.reduce((a,_,i)=>i%2===0?a.concat({a:roster[i],b:roster[i+1]}):a,[])}
function generateDynamic(t){const type=t.config.formula,stage=++t.engine.stage;let roster=t.teams.filter(x=>x.active).map(x=>x.id),pairs=[];if(roster.length<2){t.completed=true;return false}
 if(type==='double'){const losses=new Map(roster.map(id=>[id,0]));for(const m of allMatches(t)){const l=loser(m);if(m.status==='done'&&l)l.forEach(id=>losses.set(id,(losses.get(id)??0)+1))}roster=roster.filter(id=>losses.get(id)<2);if(roster.length===1){t.engine.placements[roster[0]]=1;t.completed=true;return false}const top=roster.filter(id=>losses.get(id)===0),bottom=roster.filter(id=>losses.get(id)===1);if(roster.length===2)pairs=[{a:roster[0],b:roster[1],phase:'Grande finale · 2 défaites éliminent'}];else for(const [list,title]of[[top,'Tableau principal'],[bottom,'Repêchage']]){for(let i=0;i+1<list.length;i+=2)pairs.push({a:list[i],b:list[i+1],phase:title})}}
 else {if(stage>t.config.roundCount){if(type==='ladder'){const last=t.rotations.filter(r=>r.stage===stage-1).flatMap(r=>r.matches).sort((a,b)=>t.courts.findIndex(c=>c.id===a.courtId)-t.courts.findIndex(c=>c.id===b.courtId));const order=[...last.flatMap(m=>[...(winner(m)??m.a),...(loser(m)??m.b)]),...t.engine.wait];order.forEach((id,i)=>t.engine.placements[id]=i+1)}t.completed=true;return false}
 if(type==='swiss'){roster=standings(t).filter(x=>x.active).map(x=>x.id);if(roster.length%2){const bye=roster.slice().sort((a,b)=>(t.engine.byes[a]??0)-(t.engine.byes[b]??0)||roster.indexOf(b)-roster.indexOf(a))[0];roster.splice(roster.indexOf(bye),1);t.engine.byes[bye]=(t.engine.byes[bye]??0)+1;t.engine.currentBye=bye}pairs=pairSwiss(t,roster)}
 else if(type==='americano'){const count=new Map();for(const m of allMatches(t))for(const side of[m.a,m.b])if(side.length===2){const key=side.slice().sort().join('|');count.set(key,(count.get(key)??0)+1)}const stats=standings(t),order=new Map(roster.map((id,i)=>[id,(i+stage)%roster.length]));roster.sort((a,b)=>(stats.find(x=>x.id===a)?.played??0)-(stats.find(x=>x.id===b)?.played??0)||order.get(a)-order.get(b));const selected=roster.slice(0,Math.min(Math.floor(roster.length/4),t.courts.filter(c=>c.available).length)*4);while(selected.length>=4){const a=selected.shift();selected.sort((b,c)=>(count.get([a,b].sort().join('|'))??0)-(count.get([a,c].sort().join('|'))??0));const b=selected.shift(),c=selected.shift();selected.sort((d,e)=>(count.get([c,d].sort().join('|'))??0)-(count.get([c,e].sort().join('|'))??0));pairs.push({a:[a,b],b:[c,selected.shift()],phase:'Americano'})}}
 else {if(t.engine.order)roster=t.engine.order.filter(id=>team(t,id)?.active);const cap=Math.min(t.courts.filter(c=>c.available).length,Math.floor(roster.length/2));if(type==='king'&&stage>1){const prev=t.rotations.filter(r=>r.stage===stage-1).flatMap(r=>r.matches);const kings=prev.flatMap(m=>winner(m)??m.a);const out=prev.flatMap(m=>loser(m)??m.b);const queue=[...t.engine.wait,...out].filter(id=>team(t,id)?.active);for(let i=0;i<kings.length&&queue.length;i++)pairs.push({a:kings[i],b:queue.shift(),phase:'King / Queen'});while(pairs.length<cap&&queue.length>1)pairs.push({a:queue.shift(),b:queue.shift(),phase:'King / Queen'});t.engine.wait=queue}
 else{if(type==='ladder'&&stage>1){const prev=t.rotations.filter(r=>r.stage===stage-1).flatMap(r=>r.matches);const wins=prev.flatMap(m=>winner(m)??m.a),losses=prev.flatMap(m=>loser(m)??m.b);const next=[];if(wins.length)next.push(wins[0]);for(let i=1;i<wins.length;i++){next.push(wins[i]);next.push(losses[i-1])}if(losses.length)next.push(losses.at(-1));roster=[...next,...t.engine.wait].filter(id=>team(t,id)?.active);if(t.engine.wait.length){const rested=t.engine.wait.slice();roster=roster.filter(id=>!rested.includes(id));roster.splice(Math.max(0,cap*2-rested.length),0,...rested)}t.engine.order=roster}for(let i=0;i<cap*2;i+=2)pairs.push({a:roster[i],b:roster[i+1],phase:type==='ladder'?'Montante-descendante':'King / Queen'});t.engine.wait=roster.slice(cap*2)}}}
 if(!pairs.length){t.completed=true;return false}schedule(t,pairs,null,stage);checkpoint(t);return true;
}
export function advance(t,now=Date.now()){if(!current(t).matches.every(done))throw Error('Terminez les matchs de cette rotation.');if(t.roundIndex+1<t.rotations.length){t.roundIndex++;applyAbsences(t);return true}let generated=false;
 if(t.config.formula==='poolfinal'&&t.engine.phase==='main'){const qualifiers=t.engine.groups.flatMap(g=>standings(t,g.ids).slice(0,t.config.qualifiers).map(x=>x.id));t.engine.phase='finals';t.engine.tracks=[{ids:qualifiers,start:1}];generated=generateBracket(t)}
 else if(['knockout','classification'].includes(t.config.formula)||t.engine.phase==='finals')generated=nextBracket(t);
 else if(['double','swiss','ladder','king','americano'].includes(t.config.formula))generated=generateDynamic(t);
 else t.completed=true;
 if(generated){t.roundIndex++;applyAbsences(t)}return generated;
}
export function startMatch(t,m,now=Date.now()){if(m.status==='done'||m.status==='cancelled')return;const c=t.courts.find(c=>c.id===m.courtId);if(!c?.available)throw Error('Ce terrain est indisponible.');m.status='live';if(hasTime(t)){m.clock??=clock(t.config.duration*1000);m.clock.deadline=now+m.clock.remaining;m.clock.status='running'}record(t,'start',m.id,now)}
export function startAll(t,now=Date.now()){if(t.completed)throw Error('Le tournoi est terminé.');const r=current(t);r.clock.status='running';r.clock.deadline=now+r.clock.remaining;for(const m of r.matches)if(!done(m))startMatch(t,m,now);record(t,'start-all',r.id,now)}
export function pauseAll(t,now=Date.now()){const r=current(t);if(r.clock.status==='running'){r.clock.remaining=clockLeft(r.clock,now);r.clock.status='paused';r.clock.deadline=null}for(const m of r.matches)if(m.status==='live'){if(m.clock){m.clock.remaining=clockLeft(m.clock,now);m.clock.status='paused';m.clock.deadline=null}m.status='paused'}record(t,'pause',r.id,now)}
export function addTime(t,seconds,now=Date.now()){for(const c of[current(t).clock,...current(t).matches.map(m=>m.clock).filter(Boolean)]){c.remaining=Math.max(0,c.remaining+seconds*1000);if(c.status==='running')c.deadline+=seconds*1000}record(t,'time-added',seconds,now)}
function freeze(m,now){if(m.clock){m.clock.remaining=clockLeft(m.clock,now);m.clock.status='done';m.clock.deadline=null}}
export function finishMatch(t,m,reason='manual',now=Date.now(),allowTie=true){if(done(m))return;const needsWinner=decisive(t);if(m.scoreA===m.scoreB&&allowTie&&(needsWinner||t.config.tie!=='draw')&&reason!=='forfeit'){
  m.status='live';m.tieBreak=reason==='time'&&t.config.tie==='overtime'?'overtime':'golden';m.clock=m.tieBreak==='overtime'?clock(t.config.overtime*1000):null;if(m.clock){m.clock.status='running';m.clock.deadline=now+m.clock.remaining}record(t,'tie-break',m.id,now);return;
 }m.status='done';m.reason=reason;m.tieBreak=null;freeze(m,now);record(t,'finish',m.id,now);
}
export function finishAll(t,reason='manual',now=Date.now()){for(const m of current(t).matches)if(!done(m))finishMatch(t,m,reason,now);const c=current(t).clock;c.remaining=clockLeft(c,now);c.status='done';c.deadline=null;record(t,'finish-all',reason,now)}
export function changeScore(t,m,side,delta,now=Date.now()){if(m.status==='cancelled')return false;const key=side==='a'?'scoreA':'scoreB';const next=Math.max(0,Math.min(999,m[key]+delta));if(next===m[key])return false;m[key]=next;record(t,'score',m.id,now);if(m.status==='done')return true;if(m.status==='scheduled')startMatch(t,m,now);if(m.tieBreak&&m.scoreA!==m.scoreB){finishMatch(t,m,'tie-break',now,false)}else if(hasTarget(t)&&Math.max(m.scoreA,m.scoreB)>=t.config.target&&m.scoreA!==m.scoreB){finishMatch(t,m,'target',now,false)}else return true;if(t.config.stopPolicy==='first')finishAll(t,'first-match',now);return true}
export function tick(t,now=Date.now()){const events=[];const r=current(t);if(!r)return events;const c=r.clock;if(c.status==='running'&&hasTime(t)){const left=clockLeft(c,now);for(const s of[60,30])if(left<=s*1000&&!c.alerts.includes(s)&&t.config.duration>s){c.alerts.push(s);events.push('alert'+s)}if(left===0){c.status='done';c.remaining=0;c.deadline=null;events.push('end');if(t.config.sync==='common')for(const m of r.matches)if(!done(m)&&!m.tieBreak)finishMatch(t,m,'time',now)}}
 for(const m of r.matches){if(m.status==='live'&&m.clock?.status==='running'){const left=clockLeft(m.clock,now);if(t.config.sync==='independent')for(const s of[60,30])if(left<=s*1000&&!m.clock.alerts.includes(s)&&t.config.duration>s){m.clock.alerts.push(s);events.push('alert'+s)}if(left===0){if(m.tieBreak==='overtime'&&m.scoreA===m.scoreB){m.tieBreak='golden';m.clock=null;record(t,'golden',m.id,now);events.push('state')}else{finishMatch(t,m,'time',now);events.push(t.config.sync==='independent'?'end':'state')}if(t.config.stopPolicy==='first'&&done(m))finishAll(t,'first-match',now)}}}
 if(r.matches.every(done)&&c.status==='running'){c.remaining=clockLeft(c,now);c.status='done';c.deadline=null;events.push('state')}return events;
}
export function resetRotation(t){for(const m of current(t).matches){m.status='scheduled';m.tieBreak=null;m.clock=null;m.reason=null}current(t).clock=clock(t.config.duration*1000);record(t,'reset-rotation',current(t).id)}
export function correctScore(t,matchId,a,b,discardFuture=false){
 const index=t.rotations.findIndex(r=>r.matches.some(m=>m.id===matchId));if(index<0)throw Error('Match introuvable.');if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<0||a>999||b>999)throw Error('Scores invalides.');
 const m=t.rotations[index].matches.find(m=>m.id===matchId),dynamic=!['rr','pools','levels','custom'].includes(t.config.formula),future=t.rotations.some(r=>r.stage>m.stage),wasCompleted=t.completed;
 if(dynamic&&(future||wasCompleted)){if(future&&!discardFuture)throw Error('RECALCUL_REQUIRED');const history=t.engine.history,snapshot=history?.[m.stage];if(!snapshot)throw Error('État de l’étape introuvable.');t.rotations=t.rotations.filter(r=>r.stage<=m.stage);t.roundIndex=Math.min(index,t.rotations.length-1);t.engine={...structuredClone(snapshot),history:Object.fromEntries(Object.entries(history).filter(([key])=>Number(key)<=m.stage))};t.completed=false}
 m.scoreA=a;m.scoreB=b;m.status='done';m.reason='corrected';m.tieBreak=null;freeze(m,Date.now());if(a===b&&decisive(t)){m.status='live';m.tieBreak='golden';m.clock=null;t.roundIndex=index;t.completed=false}
 else if(wasCompleted&&dynamic&&!future&&t.rotations.filter(r=>r.stage===m.stage).every(r=>r.matches.every(done))){t.roundIndex=t.rotations.length-1;advance(t)}record(t,'correct-score',m.id);return m;
}
export function applyAbsences(t){for(const m of allMatches(t)){if(done(m))continue;const a=m.a.some(id=>team(t,id)?.active===false),b=m.b.some(id=>team(t,id)?.active===false);if(!a&&!b)continue;if(a&&b){m.status='cancelled';m.reason='both-absent'}else{m.scoreA=a?0:Math.max(1,t.config.target);m.scoreB=b?0:Math.max(1,t.config.target);m.status='done';m.reason='forfeit';m.clock=null}}}
export function setAbsent(t,id,absent){const entry=team(t,id);if(!entry)throw Error('Équipe introuvable.');entry.active=!absent;if(absent)applyAbsences(t);else for(const m of t.rotations.slice(t.roundIndex).flatMap(r=>r.matches))if(m.reason==='forfeit'||m.reason==='both-absent'){if(entrants(m).includes(id)&&entrants(m).every(x=>team(t,x)?.active)){m.status='scheduled';m.scoreA=m.scoreB=0;m.reason=null}}record(t,'presence',id)}
export function setCourt(t,id,available){const c=t.courts.find(x=>x.id===id);if(!c)throw Error('Terrain introuvable.');if(!available&&t.courts.filter(c=>c.available).length===1)throw Error('Gardez au moins un terrain disponible.');c.available=available;if(!available){const r=current(t),occupied=new Set(r.matches.filter(m=>!done(m)&&m.courtId!==id).map(m=>m.courtId));const free=t.courts.find(x=>x.available&&!occupied.has(x.id));const affected=r.matches.find(m=>m.courtId===id&&!done(m));if(affected){if(free)affected.courtId=free.id;else if(affected.status==='scheduled'){r.matches.splice(r.matches.indexOf(affected),1);const insert={id:uid(),number:r.number+1,stage:affected.stage,matches:[affected],clock:clock(t.config.duration*1000)};affected.courtId=t.courts.find(x=>x.available).id;t.rotations.splice(t.roundIndex+1,0,insert)}else{if(affected.clock){affected.clock.remaining=clockLeft(affected.clock);affected.clock.status='paused';affected.clock.deadline=null}affected.status='paused'}}
 const future=t.rotations.slice(t.roundIndex+1);t.rotations=t.rotations.slice(0,t.roundIndex+1);for(const stage of[...new Set(future.map(r=>r.stage))]){const old=future.filter(r=>r.stage===stage).flatMap(r=>r.matches);schedule(t,old,null,stage)}t.rotations.forEach((r,i)=>r.number=i+1)}record(t,'court-availability',id)}
export function moveMatch(t,m,courtId){const c=t.courts.find(x=>x.id===courtId);if(!c?.available)throw Error('Terrain indisponible.');if(current(t).matches.some(x=>x.id!==m.id&&x.courtId===courtId&&!done(x)))throw Error('Ce terrain est occupé.');m.courtId=courtId;record(t,'move-match',m.id)}
export function where(t,id){const now=current(t)?.matches.find(m=>entrants(m).includes(id)&&m.status!=='cancelled');const next=t.rotations.slice(t.roundIndex+1).flatMap(r=>r.matches.map(m=>({...m,number:r.number}))).find(m=>entrants(m).includes(id)&&m.status!=='cancelled');return {now,next,rest:!now||done(now)}}
export function record(t,type,value,now=Date.now()){t.audit.push({at:now,type,value});if(t.audit.length>500)t.audit.shift()}
export function balancedTeams(participants,count,mode='balanced'){if(!participants.length)return makeTeams(count);const teams=makeTeams(Math.min(count,participants.length));let list=participants.slice();if(mode==='random')for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}else list.sort((a,b)=>(Number(b.level)||0)-(Number(a.level)||0));const totals=teams.map(()=>0);for(const p of list){const min=Math.min(...teams.map(x=>x.members.length));let choices=teams.map((x,i)=>i).filter(i=>teams[i].members.length===min);if(mode==='balanced')choices.sort((a,b)=>totals[a]-totals[b]||teams[a].members.filter(x=>x.sex===p.sex).length-teams[b].members.filter(x=>x.sex===p.sex).length);const i=choices[0];teams[i].members.push(p);totals[i]+=Number(p.level)||0}teams.forEach((x,i)=>x.level=x.members.reduce((n,p)=>n+(Number(p.level)||0),0)/Math.max(1,x.members.length));return teams}
export function multisportStandings(event){const map=new Map();const count=event.tournaments[0]?.teams.length??0;for(const t of event.tournaments){if(!t.completed)continue;for(const s of standings(t)){const e=map.get(s.id)??{id:s.id,name:s.name,color:s.color,points:0,activities:0};e.points+=count-s.rank+1;e.activities++;map.set(s.id,e)}}return [...map.values()].sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name,'fr')).map((x,i)=>({...x,rank:i+1}))}
